<script setup lang="ts">
import { onMounted, onUnmounted, ref, watch } from 'vue'
import {useRoute,useRouter} from 'vue-router'
import { api, beijingTime } from './api'
import { errorMessage, type Preview, type Settings } from './monitoring'
import RecordDelete from './RecordDelete.vue'
interface Backup {id:string;time:number;revision:string;source:string;restored:number;result:string;can_delete:boolean;delete_reason:string;needs_completion:boolean}
const route=useRoute(),router=useRouter();let generation=0,disposed=false
const items=ref<Backup[]>([]),total=ref(0),page=ref(Math.max(1,Number(route.query.deployment_page)||1)),error=ref(''),feedback=ref(''),preview=ref<Preview&{token:string;credentials:string;path_notice:string}>(),selected=ref(''),settings=ref<Settings>(),checked=ref<Backup[]>([]),deletion=ref<InstanceType<typeof RecordDelete>>(),busy=ref(false),keepCredentials=ref(true)
const byteLength=(value:string)=>new TextEncoder().encode(value).length
const file=ref<HTMLInputElement>(),importing=ref<File>(),cryptoDialog=ref(false),exportID=ref(''),password=ref(''),confirmation=ref(''),secure=location.protocol==='https:'
async function load(){const current=++generation;try{const [list,config]=await Promise.all([api<{items:Backup[];total:number}>(`/api/config-backups?page=${page.value}`),api<Settings>('/api/settings')]);if(current===generation&&!disposed){items.value=list.items;total.value=list.total;settings.value=config;checked.value=[];error.value='';if(page.value>Math.max(1,Math.ceil(list.total/20))){page.value=Math.max(1,Math.ceil(list.total/20));await load()}}}catch(e){if(current===generation&&!disposed)error.value=errorMessage(e)}}
async function create(){busy.value=true;try{await api('/api/config-backups','POST');feedback.value='当前磁盘 YAML 已备份，可能包含尚未应用修改';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function inspect(id:string){selected.value=id;preview.value=undefined;busy.value=true;try{preview.value=await api(`/api/config-backups/${id}/preview`,'POST',{revision:settings.value?.revision,keep_credentials:keepCredentials.value});const row=items.value.find(b=>b.id===id);if(row){row.can_delete=false;row.delete_reason='恢复预览仍有效'}}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function restore(){if(!preview.value)return;busy.value=true;try{await api(`/api/config-backups/${selected.value}/restore`,'POST',{revision:settings.value?.revision,token:preview.value.token,keep_credentials:keepCredentials.value});preview.value=undefined;feedback.value='已恢复为待应用配置，请到系统设置检查并应用';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
function download(content:string,filename:string,encrypted:boolean){const bytes=encrypted?Uint8Array.from(atob(content),c=>c.charCodeAt(0)):content;const url=URL.createObjectURL(new Blob([bytes],{type:encrypted?'application/octet-stream':'application/yaml'})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function exportFile(id:string,encrypted=false){busy.value=true;try{const doc=await api<{content:string;filename:string;encrypted:boolean}>(`/api/config-backups/${id}/export`,'POST',{encrypted,password:encrypted?password.value:undefined,confirm_password:encrypted?confirmation.value:undefined});download(doc.content,doc.filename,doc.encrypted);cryptoDialog.value=false}catch(e){error.value=errorMessage(e)}finally{busy.value=false;password.value='';confirmation.value=''}}
function openEncrypted(id:string){exportID.value=id;importing.value=undefined;password.value='';confirmation.value='';cryptoDialog.value=true}
async function chooseFile(event:Event){const input=event.target as HTMLInputElement,chosen=input.files?.[0];input.value='';if(!chosen)return;if(chosen.name.endsWith('.age')){if(!secure){error.value='加密导入仅允许 HTTPS 后台';return};if(chosen.size>4*1024*1024){error.value='加密包不能超过 4 MiB';return};importing.value=chosen;exportID.value='';password.value='';cryptoDialog.value=true}else{await importFile(chosen,false)}}
async function importFile(chosen:File,encrypted:boolean){busy.value=true;try{if(chosen.size>(encrypted?4:2)*1024*1024)throw new Error('文件超过大小限制');const content=encrypted?btoa(Array.from(new Uint8Array(await chosen.arrayBuffer()),b=>String.fromCharCode(b)).join('')):await chosen.text();await api('/api/config-backups/import','POST',{content,encrypted,password:encrypted?password.value:undefined});feedback.value='导入仅加入备份历史，未覆盖 YAML 或部署';cryptoDialog.value=false;await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false;password.value='';confirmation.value=''}}
watch(keepCredentials,()=>{preview.value=undefined})
watch(()=>route.fullPath,()=>{page.value=Math.max(1,Number(route.query.deployment_page)||1);preview.value=undefined;checked.value=[];void load()})
onMounted(load);onUnmounted(()=>{disposed=true;generation++;password.value='';confirmation.value=''})
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="feedback" :title="feedback" type="success" closable @close="feedback=''"/><el-card shadow="never"><div class="card-heading"><h3>部署配置备份</h3><div class="filters"><el-button type="primary" :loading="busy" @click="create">手动备份</el-button><el-button @click="file?.click()">导入 YAML / age 包</el-button><RecordDelete ref="deletion" :records="checked" label="部署配置备份" endpoint="/api/config-backups/delete" @done="load"/></div></div><p class="muted">磁盘 YAML 与已应用配置可能不同。默认导出脱敏 YAML；包含 YAML 凭据的 age 密码加密包只允许 HTTPS。</p><input ref="file" type="file" accept=".yaml,.yml,.age" hidden @change="chooseFile"/><el-table :data="items" @selection-change="checked=$event"><el-table-column type="selection" :selectable="(row:Backup)=>row.can_delete" width="48"/><el-table-column label="时间" min-width="180"><template #default="{row}">{{beijingTime(row.time)}}</template></el-table-column><el-table-column prop="source" label="来源"/><el-table-column prop="revision" label="配置版本" show-overflow-tooltip/><el-table-column label="恢复及保护" min-width="180"><template #default="{row}">{{row.needs_completion?'脱敏配置，需核对补全；':''}}{{row.result||'尚未恢复'}}<small class="muted">{{row.delete_reason}}</small></template></el-table-column><el-table-column label="操作" min-width="280"><template #default="{row}"><el-button link type="primary" @click="exportFile(row.id)">脱敏导出</el-button><el-button link :disabled="!secure||busy" @click="openEncrypted(row.id)">加密导出</el-button><el-button link type="primary" @click="inspect(row.id)">恢复预览</el-button><el-button link type="danger" :disabled="!row.can_delete" :title="row.delete_reason" @click="deletion?.open([row])">删除</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @change="router.replace({path:'/backups',query:{...route.query,deployment_page:String(page)}})"/></el-card>
<el-card shadow="never"><h3>恢复选项</h3><el-checkbox v-model="keepCredentials">保留当前凭据（默认；节点按唯一 ID 匹配）</el-checkbox><p class="muted">取消后使用备份中的凭据；备份缺失字段仍保留当前值。新增节点缺少认证、地址或本机私钥时，服务端拒绝恢复。</p></el-card><el-card v-if="preview" shadow="never"><h3>恢复影响（10 分钟有效）</h3><p>{{preview.credentials}}</p><p>{{preview.path_notice}}</p><p>影响节点：{{preview.nodes.join('、')||'主服务器'}}；应用范围：{{preview.scope}}。</p><el-table :data="preview.changes"><el-table-column prop="field" label="字段"/><el-table-column prop="before" label="原值"/><el-table-column prop="after" label="新值"/><el-table-column prop="effect" label="影响"/></el-table><p>恢复前自动备份当前配置；恢复后为待应用，不会立即部署。</p><el-button type="primary" :loading="busy" @click="restore">确认恢复为待应用配置</el-button></el-card>
<el-dialog v-model="cryptoDialog" :title="importing?'解密并导入备份':'包含 YAML 凭据的 age 加密导出'" width="min(540px,96vw)" @closed="password='';confirmation='' "><p>密码仅用于本次操作，请妥善保存。配置包不包含外部私钥、PKI 或监控数据库。</p><el-input v-model="password" type="password" show-password placeholder="至少 12 字节密码" autocomplete="new-password"/><el-input v-if="!importing" v-model="confirmation" type="password" show-password placeholder="再次输入密码" autocomplete="new-password"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="cryptoDialog=false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!secure||byteLength(password)<12||!importing&&password!==confirmation" @click="importing?importFile(importing,true):exportFile(exportID,true)">{{importing?'导入到备份列表':'加密并下载'}}</el-button></template></el-dialog></template>
